-- SOP for the new boat Full Detail package.
insert into public.service_guides (key, asset_type, title, summary, time_estimate, crew, products, tools, prep, steps, donts, quality_checks, photos) values
(
  'boat_full_detail',
  'watercraft',
  'Full Detail (Inside & Out)',
  'The complete package: a full hull and deck wash, a one-step polish with protection on the gelcoat, metal polished, vinyl and clear windows cleaned and protected, and a full interior clean. Sell it two to four times a year, or as the first visit before a maintenance plan.',
  'Under 25 ft 4–6 h · 25–40 ft 6–10 h · 40 ft+ 1–2 days',
  '2 technicians',
  array['Biodegradable marine boat soap (wax-safe)', 'One-step marine cleaner wax', 'Marine metal polish', 'Marine vinyl cleaner and UV protectant', 'Marine glass/isinglass cleaner (vinyl window safe)', 'Marine-safe disinfectant for heads and galley']::text[],
  array['Hose with adjustable nozzle and fresh water', 'Soft deck brush on extension pole', 'Dual-action polisher with marine pads', 'Masking tape', 'Shop vacuum (cordless or GFCI-protected)', 'Color-coded microfiber towels', 'Synthetic chamois and water blade']::text[],
  array['Confirm marina/yard rules for washing, chemicals and runoff', 'Walk the vessel with the owner and photograph existing damage', 'Secure the boat and use non-slip footwear', 'Protect electronics and open electrical panels', 'Confirm the scope and any no-go areas']::text[],
  '[{"title": "Walk vessel & agree scope", "detail": "Walk the boat with the owner. Photograph existing damage, oxidation, stains and torn vinyl. Agree what is included (hull, deck, interior, metal, canvas) and any no-go areas such as private lockers or the engine room.", "caution": "Report new damage, water in the bilge or chafed lines before starting.", "minutes": 15, "products": []}, {"title": "Secure boat & check marina rules", "detail": "Confirm washing and chemical rules with the marina or yard, set up runoff containment if required, double the lines or check the stands, and wear non-slip footwear.", "caution": "Never work from the gunwale or lean over lifelines to reach the hull.", "minutes": 10, "products": []}, {"title": "Close up & protect electronics", "detail": "Close hatches and ports, zip enclosures, cover helm displays and open switch panels.", "caution": null, "minutes": 10, "products": []}, {"title": "Full wash top-down", "detail": "Rinse and hand wash from the hardtop down to the waterline with biodegradable marine soap: canvas frames, hardware, glass, gelcoat, non-skid (deck brush) and the swim platform. Rinse well and dry with a chamois and water blade.", "caution": "Do not let soap or salt dry on gelcoat or glass in the sun.", "minutes": 90, "products": []}, {"title": "Hull & deck polish with protection", "detail": "Machine polish the topsides and smooth gelcoat with a one-step marine cleaner wax to lift light oxidation and leave protection. Work small sections, wipe off fully, and keep product off non-skid.", "caution": "Mask decals, rub rails and seams. Heavy oxidation needs the Compound & Wax service instead.", "minutes": 180, "products": []}, {"title": "Metal & brightwork", "detail": "Polish stainless rails, cleats and hardware with a marine metal polish and protect it.", "caution": "Keep polish off teak and canvas.", "minutes": 40, "products": []}, {"title": "Vinyl, canvas & clear windows", "detail": "Clean and protect seats and vinyl with a pH-neutral marine vinyl cleaner and UV protectant; clean clear vinyl with a vinyl-safe cleaner and soft microfiber.", "caution": "Never dry-wipe isinglass or use ammonia, bleach or magic erasers on vinyl.", "minutes": 45, "products": []}, {"title": "Interior clean", "detail": "Vacuum and wipe the cabin, salon, head and galley; sanitize the head and galley, clean glass and mirrors, and treat light mildew.", "caution": "Never mix chemicals in the confined head. Ventilate the cabin.", "minutes": 90, "products": []}, {"title": "Final walk-through & photos", "detail": "Walk the boat with fresh eyes, touch up any residue, take after photos, put everything back as the owner left it and record products used.", "caution": null, "minutes": 15, "products": []}]'::jsonb,
  array['Never use household soap where runoff reaches the water', 'Never polish or wax non-skid, steps or the swim platform', 'Never use ammonia, bleach or magic erasers on vinyl or isinglass', 'Never run cords through water or across walkways', 'Never open private lockers without permission']::text[],
  array['Gelcoat glossy with no wax residue in seams or on decals', 'Non-skid clean and not slippery', 'Metal bright with no polish residue', 'Vinyl and clear windows clean and streak-free', 'Interior clean, dry and odor-free, and the boat closed up as the owner left it']::text[],
  array['Before: bow, stern, port and starboard', 'Before: close-ups of oxidation, stains and damage', 'After: same four angles', 'After: helm, cockpit and cabin']::text[]
)
on conflict do nothing;
